(()=>{const fields=()=>[...document.querySelectorAll('input,select,textarea')].filter(e=>e.type!=='file');document.getElementById('saveEvaluation').onclick=()=>{const data={format:'nexus-evaluation',version:1,values:fields().map(e=>({value:e.value,checked:Boolean(e.checked)}))};const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='neXus_Bewertung.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),15000);};document.getElementById('loadEvaluation').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const d=JSON.parse(await f.text());const els=fields();if(d.format!=='nexus-evaluation'||d.version!==1||!Array.isArray(d.values)||d.values.length!==els.length||d.values.some(v=>typeof v.value!=='string'||typeof v.checked!=='boolean'))throw Error('Datei passt nicht zu diesem Bewertungsrechner.');d.values.forEach((v,i)=>{els[i].value=v.value;els[i].checked=v.checked;});els.forEach(el=>el.dispatchEvent(new Event('change',{bubbles:true})));els.forEach(el=>el.dispatchEvent(new Event('input',{bubbles:true})));document.getElementById('backupStatus').textContent='Bewertung importiert.';}catch(err){alert('Import nicht möglich: '+err.message);}finally{e.target.value='';}};})();